namespace FullWorth.ParserWorker.Ocr;

internal static class OcrRuntimeProbe
{
    private const string ProbeImageBase64 =
        "";

    internal static byte[] ImageBytes { get; } =
        Convert.FromBase64String(ProbeImageBase64);

    internal static bool IsHealthy(BillStatementOcrResult result) =>
        result.PageCount == 1 &&
        !string.IsNullOrWhiteSpace(result.Text) &&
        result.MeanConfidence is > 0f and <= 1f;
}
